// Script to validate environment variables and API keys
// This script checks connectivity and key validity without making destructive calls.

const dotenv = require('dotenv');
dotenv.config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

// Helper function to log results
function logResult(service, isValid, message) {
  console.log(`[${service}] ${isValid ? '✅ Valid' : '❌ Invalid'}: ${message}`);
}

// Test 1: Database Connectivity (PostgreSQL)
async function testDatabase() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    logResult('Database', false, 'DATABASE_URL not set');
    return;
  }

  const client = new Client({ connectionString: databaseUrl });
  try {
    await client.connect();
    logResult('Database', true, 'Connected successfully');
    await client.end();
  } catch (error) {
    logResult('Database', false, `Connection failed: ${error.message}`);
  }
}

// Test 2: AWS Credentials (AWS S3 ListBuckets)
async function testAws() {
  const awsAccessKey = process.env.AWS_ACCESS_KEY_ID;
  const awsSecretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!awsAccessKey || !awsSecretKey) {
    logResult('AWS', false, 'AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY not set');
    return;
  }

  const s3 = new AWS.S3({ 
    accessKeyId: awsAccessKey, 
    secretAccessKey: awsSecretKey, 
    region: 'us-east-1' 
  });

  try {
    await s3.listBuckets().promise();
    logResult('AWS', true, 'Authentication successful');
  } catch (error) {
    logResult('AWS', false, `Authentication failed: ${error.message}`);
  }
}

// Test 3: Anthropic API Key (Basic Validation)
async function testAnthropic() {
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (!anthropicKey) {
    logResult('Anthropic', false, 'ANTHROPIC_API_KEY not set');
    return;
  }

  // Test with a simple API call (e.g., validate auth)
  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/complete',
      { prompt: 'Test', max_tokens_to_sample: 1 },
      { headers: { 'Authorization': `Bearer ${anthropicKey}`, 'Content-Type': 'application/json' } }
    );
    if (response.data.error) {
      logResult('Anthropic', false, `API error: ${response.data.error.message}`);
    } else {
      logResult('Anthropic', true, 'API key is valid');
    }
  } catch (error) {
    logResult('Anthropic', false, `API call failed: ${error.message}`);
  }
}

// Test 4: Stripe API Key (Basic Validation)
async function testStripe() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    logResult('Stripe', false, 'STRIPE_SECRET_KEY not set');
    return;
  }

  try {
    const stripe = require('stripe')(stripeKey);
    await stripe.customers.list({ limit: 1 }); // Non-destructive call
    logResult('Stripe', true, 'API key is valid');
  } catch (error) {
    logResult('Stripe', false, `API call failed: ${error.message}`);
  }
}

// Test 5: Logfire Token (Minimal Test)
async function testLogfire() {
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (!logfireToken) {
    logResult('Logfire', false, 'LOGFIRE_TOKEN not set');
    return;
  }

  // Placeholder: Logfire validation logic (if applicable)
  logResult('Logfire', false, 'Unchecked: Logfire validation requires specific endpoint logic');
}

// Run all tests
async function runTests() {
  console.log('Starting credential validation...\n');
  await testDatabase();
  await testAws();
  await testAnthropic();
  await testStripe();
  await testLogfire();
  console.log('\nValidation complete.');
}

runTests().catch(console.error);

