// Script to validate environment variables and API keys
// This script checks connectivity and key validity without making destructive calls.

const dotenv = require('dotenv');
dotenv.config({ path: '.env.test' });

// Helper function to log results
function logResult(service, isValid, message) {
  console.log(`[${service}] ${isValid ? '✅ Valid' : '❌ Invalid'}: ${message}`);
}

// Validate Database URL format
function testDatabaseUrl() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    logResult('Database', false, 'DATABASE_URL not set');
    return;
  }

  // Regex to validate PostgreSQL connection string
  const postgresRegex = /^postgres:\/\/[a-zA-Z0-9_]+:[a-zA-Z0-9_@]+@[a-zA-Z0-9.]+:\d+\/[a-zA-Z0-9_]+$/;
  if (postgresRegex.test(databaseUrl)) {
    logResult('Database', true, 'URL format is valid');
  } else {
    logResult('Database', false, 'Invalid URL format');
  }
}

// Validate AWS key format
function testAwsKeys() {
  const awsAccessKey = process.env.AWS_ACCESS_KEY_ID;
  const awsSecretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!awsAccessKey || !awsSecretKey) {
    logResult('AWS', false, 'AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY not set');
    return;
  }

  // Regex to validate AWS access key format
  const accessKeyRegex = /^AKIA[0-9A-Z]{16}$/;
  // Regex to validate AWS secret key format
  const secretKeyRegex = /^[a-zA-Z0-9\/+=]{40}$/;

  if (accessKeyRegex.test(awsAccessKey) && secretKeyRegex.test(awsSecretKey)) {
    logResult('AWS', true, 'AWS key format is valid');
  } else {
    logResult('AWS', false, 'Invalid AWS key format');
  }
}

// Validate Anthropic API key format
function testAnthropicKey() {
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (!anthropicKey) {
    logResult('Anthropic', false, 'ANTHROPIC_API_KEY not set');
    return;
  }

  // Regex to validate Anthropic API key format (starts with 'sk-ant-')
  const anthropicRegex = /^sk-ant-[a-zA-Z0-9-]{10,}$/;
  if (anthropicRegex.test(anthropicKey)) {
    logResult('Anthropic', true, 'API key format is valid');
  } else {
    logResult('Anthropic', false, 'Invalid API key format');
  }
}

// Validate Stripe API key format
function testStripeKey() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    logResult('Stripe', false, 'STRIPE_SECRET_KEY not set');
    return;
  }

  // Regex to validate Stripe API key format (starts with 'sk_live_' or 'sk_test_')
  const stripeRegex = /^(sk_live_|sk_test_)[a-zA-Z0-9_]{24,}$/;
  if (stripeRegex.test(stripeKey)) {
    logResult('Stripe', true, 'API key format is valid');
  } else {
    logResult('Stripe', false, 'Invalid API key format');
  }
}

// Validate Logfire Token format
function testLogfireToken() {
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (!logfireToken) {
    logResult('Logfire', false, 'LOGFIRE_TOKEN not set');
    return;
  }

  // Logfire tokens are typically alphanumeric strings
  const logfireRegex = /^[a-zA-Z0-9-]{10,}$/;
  if (logfireRegex.test(logfireToken)) {
    logResult('Logfire', true, 'Token format is valid');
  } else {
    logResult('Logfire', false, 'Invalid token format');
  }
}

// Run all tests
function runTests() {
  console.log('Starting credential validation...\n');
  testDatabaseUrl();
  testAwsKeys();
  testAnthropicKey();
  testStripeKey();
  testLogfireToken();
  console.log('\nValidation complete.');
}

runTests();

